// Accepts either a JSON array or a CSV string. One item per contact.
function parseCsv(text) {
  const lines = String(text).split(/\r?\n/).filter((l) => l.trim() !== '');
  if (!lines.length) return [];
  const head = lines[0].split(',').map((h) => h.trim().toLowerCase());
  return lines.slice(1).map((line) => {
    const cells = line.split(',');
    const row = {};
    head.forEach((h, i) => { row[h] = (cells[i] || '').trim(); });
    return row;
  });
}
const out = [];
for (const item of $input.all()) {
  const data = item.json.data !== undefined ? item.json.data : item.json;
  const rows = Array.isArray(data) ? data : (typeof data === 'string' ? parseCsv(data) : [data]);
  for (const r of rows) {
    out.push({ json: { lead: {
      name: r.name || r.full_name || '',
      handle: r.profile || r.profile_url || '',
      company: r.company || r.current_company || '',
      title: r.title || r.headline || '',
      last_inbound_message: r.message || r.note || '',
      email: (r.email || '').toLowerCase(),
      source: 'linkedin_inbound',
      consent_basis: 'legitimate_interest',
      consent_recorded_at: new Date().toISOString()
    } } });
  }
}
return out;

// Four buckets. Recruiters and peers are not leads and must not enter the sales pipeline.
const RECRUITER = ['recruiter', 'talent', 'hiring for', 'opportunity at', 'staffing', 'headhunter'];
const SPAM = ['guaranteed leads', 'seo services', 'ranking', 'crypto', 'investment opportunity', 'buy followers', 'cheap developers'];
const PEER = ['agency owner', 'founder', 'let us connect', 'love your content', 'fellow'];
const BUYING = ['need help', 'looking for', 'can you build', 'quote', 'proposal', 'budget', 'project', 'hire you'];
return $input.all().map((item) => {
  const lead = item.json.lead || {};
  const text = [lead.last_inbound_message, lead.title].join(' ').toLowerCase();
  const hit = (l) => l.some((k) => text.includes(k));
  let bucket = 'peer';
  if (hit(SPAM)) bucket = 'spam';
  else if (hit(RECRUITER)) bucket = 'recruiter';
  else if (hit(BUYING)) bucket = 'lead';
  return { json: Object.assign({}, item.json, { bucket, lead: Object.assign({}, lead, { bucket }) }) };
});

// Build the request the rails expect. Missing fields are denied, not defaulted:
// the rails fail closed on purpose.
return $input.all().map((item) => {
  const lead = item.json.lead || item.json;
  return { json: Object.assign({}, item.json, { rails_request: {
    channel: 'linkedin',
    purpose: 'crm_write',
    contact_email: lead.email || '',
    contact_phone: lead.phone || '',
    contact_handle: lead.handle || '',
    inbound_message: lead.last_inbound_message || '',
    consent: { basis: lead.consent_basis || null, recorded_at: lead.consent_recorded_at || null },
    estimated_cost_usd: Number(lead.estimated_cost_usd || 0),
    workflow: $workflow.name
  } }) };
});

// The rails said no. Record it and stop. A denied action is never retried.
return $input.all().map((item) => ({ json: {
  blocked: true,
  code: item.json.code || 'denied',
  reason: item.json.reason || 'Safety rails denied this action.',
  contact: item.json.rails_request ? item.json.rails_request.contact_email : null,
  workflow: $workflow.name,
  at: new Date().toISOString()
} }));

